def longest_word(words):
    if not words:
        return None
    return max(words, key=len)

def rotate_items(items, k):
    import operator

    k = operator.index(k)
    if k < 0:
        raise ValueError("k must be nonnegative")

    items = tuple(items)
    if not items:
        return None

    k %= len(items)
    if k == 0:
        return items
    return items[-k:] + items[:-k]

def sort_labels(labels):
    iterator = iter(labels)
    try:
        first = next(iterator)
    except StopIteration:
        return None

    seen = {}
    for label in (first, *iterator):
        key = label.casefold() if isinstance(label, str) else label
        if key not in seen:
            seen[key] = label

    return tuple(
        sorted(
            seen.values(),
            key=lambda label: (
                0,
                label.casefold(),
            )
            if isinstance(label, str)
            else (1, type(label).__name__, repr(label)),
        )
    )

def find_products(products, query):
    if not products:
        return None

    query = query.casefold()
    matches = [product for product in products if query in product["name"].casefold()]
    return tuple(sorted(matches, key=lambda product: product["score"], reverse=True))

def group_words(words):
    if not words:
        return None

    groups = {}
    for word in words:
        key = word[0].casefold()
        groups.setdefault(key, []).append(word)

    return {key: tuple(group) for key, group in groups.items()}

def parse_integer_fields(fields):
    if len(fields) == 0:
        return None
    return tuple(int(field) for field in fields)

def nearest_date(dates, target):
    from datetime import date

    iterator = iter(dates)
    try:
        closest = next(iterator)
    except StopIteration:
        return None

    target_date = date.fromisoformat(target)
    closest_distance = abs((date.fromisoformat(closest) - target_date).days)

    for candidate in iterator:
        distance = abs((date.fromisoformat(candidate) - target_date).days)
        if distance < closest_distance:
            closest = candidate
            closest_distance = distance

    return closest

def median_value(values):
    if not values:
        return None
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    sorted_ranges = sorted(ranges, key=lambda r: r[0])
    merged = [[sorted_ranges[0][0], sorted_ranges[0][1]]]

    for start, end in sorted_ranges[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return tuple((start, end) for start, end in merged)

def shortest_path(graph, start, goal):
    from collections import deque

    if start == goal:
        return (start,)

    queue = deque([start])
    previous = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, ()):
            if neighbor in previous:
                continue
            previous[neighbor] = node
            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = previous[current]
                return tuple(reversed(path))
            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    nodes = tuple(nodes)
    if not nodes:
        return None

    node_set = set(nodes)
    adjacency = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for source, destination in edges:
        if source in node_set and destination in node_set:
            adjacency[source].append(destination)
            indegree[destination] += 1

    ready = [node for node in nodes if indegree[node] == 0]
    order = []

    while ready:
        node = ready.pop(0)
        order.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                ready.append(destination)

    if len(order) != len(node_set):
        raise ValueError("graph contains a cycle")

    return tuple(order)
